void gbMatrix4::operator*=(float const * p0) {
    float tmp[4][4];
    memcpy(tmp, m, sizeof(tmp));
    for (int i = 0; i < 4; i++) {
        for (int j = 0; j < 4; j++) {
            m[i][j] = 0.0f;
            for (int k = 0; k < 4; k++) {
                m[i][j] += tmp[i][k] * p0[k * 4 + j];
            }
        }
    }
}

