void gbMatrix4::RightScale(float p0, float p1, float p2) {
    m[0][0] *= p0; m[1][0] *= p0; m[2][0] *= p0; m[3][0] *= p0;
    m[0][1] *= p1; m[1][1] *= p1; m[2][1] *= p1; m[3][1] *= p1;
    m[0][2] *= p2; m[1][2] *= p2; m[2][2] *= p2; m[3][2] *= p2;
}

